"use client";

import { useState } from "react";

import { IconAward, IconBookOpen, IconInfinity, IconVideo } from "@rhs-ui/icons";
import { CourseEnrollHero } from "@rhs-ui/marketing/course-enroll-hero";

/* The poster is drawn for the demo, so it needs no file: the sheet of a design system, in its dark theme. In your site: a still from the course. */
function poster(): string {
  let art = "<rect width='1280' height='720' fill='#161616'/>";
  const label = (text: string, x: number, y: number) => `<text x='${x}' y='${y}' font-size='15' font-weight='600' letter-spacing='3' fill='#8c8c8c'>${text}</text>`;
  art += label("COLOR", 96, 96);
  ["#f4f4f4", "#cfcfcf", "#9a9a9a", "#6a6a6a", "#3a3a3a", "#262626"].forEach((fill, index) => {
    art += `<rect x='${96 + (index % 3) * 88}' y='${116 + Math.floor(index / 3) * 88}' width='72' height='72' rx='16' fill='${fill}'/>`;
  });
  art += label("TYPE", 96, 340);
  art += "<text x='92' y='452' font-size='128' font-weight='600' letter-spacing='-4' fill='#ededed'>Aa</text><text x='284' y='452' font-size='56' font-weight='600' letter-spacing='-2' fill='#9a9a9a'>Aa</text>";
  art += label("SPACE", 96, 520);
  [8, 16, 24, 32, 48].forEach((size, index) => {
    art += `<rect x='${96 + index * 56}' y='${540 + (48 - size)}' width='${size}' height='${size}' rx='3' fill='#ededed' opacity='${0.35 + index * 0.16}'/>`;
  });
  art += label("COMPONENTS", 440, 96);
  art += "<rect x='440' y='120' width='180' height='56' rx='14' fill='#ededed'/><text x='530' y='155' font-size='19' font-weight='600' text-anchor='middle' fill='#161616'>Button</text>";
  art += "<rect x='644' y='120.5' width='180' height='55' rx='14' fill='none' stroke='#3a3a3a' stroke-width='2'/><text x='734' y='155' font-size='19' font-weight='600' text-anchor='middle' fill='#ededed'>Button</text>";
  art += "<rect x='864' y='132' width='76' height='32' rx='16' fill='#ededed'/><circle cx='924' cy='148' r='12' fill='#161616'/>";
  art += "<rect x='980' y='132' width='32' height='32' rx='9' fill='#ededed'/><path d='M988 148l6 6 12-12' stroke='#161616' stroke-width='3.4' fill='none' stroke-linecap='round' stroke-linejoin='round'/><rect x='1028' y='142' width='96' height='12' rx='6' fill='#5a5a5a'/>";
  art += "<rect x='440' y='204' width='520' height='56' rx='14' fill='none' stroke='#3a3a3a' stroke-width='2'/><text x='464' y='239' font-size='19' fill='#6a6a6a'>Email address</text>";
  art += "<rect x='984' y='204' width='200' height='56' rx='14' fill='#262626'/><rect x='1008' y='226' width='108' height='12' rx='6' fill='#8c8c8c'/>";
  [440, 696, 952].forEach((x, index) => {
    art += `<rect x='${x}' y='296' width='232' height='264' rx='22' fill='#1f1f1f' stroke='#2e2e2e' stroke-width='2'/>`;
    art += `<rect x='${x + 24}' y='320' width='44' height='44' rx='12' fill='${index === 0 ? "#ededed" : "#2e2e2e"}'/>`;
    art += `<rect x='${x + 24}' y='392' width='${124 - index * 14}' height='14' rx='7' fill='#ededed'/><rect x='${x + 24}' y='420' width='184' height='9' rx='4.5' fill='#5a5a5a'/><rect x='${x + 24}' y='438' width='152' height='9' rx='4.5' fill='#444'/>`;
    art += `<rect x='${x + 24}' y='488' width='100' height='36' rx='18' ${index === 1 ? "fill='#ededed'" : "fill='none' stroke='#3a3a3a' stroke-width='2'"}/>`;
  });
  return "data:image/svg+xml;utf8," + encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 720' font-family='Segoe UI, Helvetica, Arial, sans-serif'>${art}</svg>`);
}

/* A portrait drawn for the demo. In your site: the teacher's real photo. */
const portrait =
  "data:image/svg+xml;utf8," +
  encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'><rect width='40' height='40' fill='#d9d7d2'/><circle cx='20' cy='16' r='7' fill='#7a776f'/><path d='M5 40c0-9 7-14 15-14s15 5 15 14Z' fill='#7a776f'/></svg>");

/* Four seconds of a lesson title card, as a small silent mp4 (640 by 360). In your site: your own preview file. */
const lesson = "data:video/mp4;base64,";

const includes = [
  { icon: <IconVideo />, label: "14 hours of on-demand video" },
  { icon: <IconBookOpen />, label: "62 lessons and 9 projects" },
  { icon: <IconAward />, label: "Certificate of completion" },
  { icon: <IconInfinity />, label: "Lifetime access, with every update" },
];

const lessons: readonly (readonly [title: string, minutes: number])[] = [
  ["Write for the person, not the product", 9],
  ["Buttons, labels and the words in between", 12],
  ["Errors that help instead of blame", 14],
  ["Empty states and first-run screens", 11],
  ["Release notes people actually read", 13],
  ["Email and in-app announcements", 10],
  ["A voice guide in one page", 8],
  ["Review, edit and ship", 15],
];

export default function Demo(): React.JSX.Element {
  // onEnroll hands the click to your app; here it only counts, so the press can be seen.
  const [presses, setPresses] = useState(0);
  return (
    <div className="mx-auto max-w-6xl px-6">
      <p className="pt-6 text-xs text-muted-foreground">With a preview video and a former price: the poster opens the lesson in a dialog.</p>
      <CourseEnrollHero
        className="py-8 sm:py-10"
        course={{
          category: "Design systems",
          title: "Design systems that scale",
          promise: "Build the tokens, components and documentation that let ten teams ship one product, taught by the designer who built Halcyon's.",
          poster: { src: poster(), alt: "A design system sheet: colour swatches, type, buttons, an input and three cards", width: 1280, height: 720 },
          video: { src: lesson, title: "Lesson 1: Tokens before components", duration: "0:04" },
        }}
        instructor={{ name: "Marta Vos", role: "Principal designer at Halcyon", avatar: portrait }}
        rating={{ value: 4.8, count: 2314 }}
        learners={12480}
        outcomes={[
          "Turn scattered styles into tokens that every team can trust",
          "Build and document a component library, from the first button to the last",
          "Ship releases, versions and migrations without breaking a product",
        ]}
        price={{ amount: 8900, currency: "EUR", was: 12900 }}
        includes={includes}
        guarantee="30-day money-back guarantee. No questions asked."
        onEnroll={() => setPresses((count) => count + 1)}
      />
      <p role="status" className="min-h-4 text-xs text-foreground">
        {presses ? `Enrol now pressed ${presses} ${presses === 1 ? "time" : "times"}. In your app, this is where the checkout starts.` : ""}
      </p>

      <p className="border-t border-border pt-6 text-xs text-muted-foreground">Without a preview, a plain price and a link to your checkout. The page's own content goes in as children, and the card stays beside it while it scrolls.</p>
      <CourseEnrollHero
        className="py-8 sm:py-10"
        course={{
          category: "Writing",
          title: "Writing for product teams",
          promise: "Clearer interfaces, calmer launches and release notes people read, in eight short lessons.",
          poster: { src: poster(), alt: "", width: 1280, height: 720 },
        }}
        instructor={{ name: "Jonas Eriksen", role: "Head of content at Kestrel" }}
        rating={{ value: 4.6, count: 861 }}
        learners={3920}
        outcomes={["Write interface copy that needs no explaining", "Plan a launch from the first draft to the last email"]}
        price={{ amount: 4900, currency: "EUR" }}
        includes={includes.slice(0, 3)}
        enrollHref="#checkout"
        guarantee="Refunds within 14 days."
      >
        <h3 className="text-sm font-medium">Curriculum</h3>
        <ol className="mt-4 divide-y divide-border border-y border-border">
          {lessons.map(([title, minutes], index) => (
            <li key={title} className="flex items-baseline gap-4 py-3 text-sm">
              <span className="w-5 text-muted-foreground tabular-nums">{index + 1}</span>
              <span className="min-w-0 flex-1">{title}</span>
              <span className="shrink-0 text-muted-foreground tabular-nums">{minutes} min</span>
            </li>
          ))}
        </ol>
      </CourseEnrollHero>
    </div>
  );
}
